DROP TABLE IF EXISTS `dorm_static_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dorm_static_info` (
  `DORM` text COLLATE utf8_unicode_ci,
  `ADDRESS` text COLLATE utf8_unicode_ci,
  `DESCRIPTION` text COLLATE utf8_unicode_ci,
  `SHORT_DESCRIPTION` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL,
  `COLLEGE` text COLLATE utf8_unicode_ci,
  `THUMBNAIL_IMAGE` text COLLATE utf8_unicode_ci,
  `WALKTHROUGH` int(11) DEFAULT NULL,
  `SINGLE_` int(11) DEFAULT NULL,
  `DOUBLE_` int(11) DEFAULT NULL,
  `TRIPLE_` int(11) DEFAULT NULL,
  `PROS` text COLLATE utf8_unicode_ci,
  `CONS` text COLLATE utf8_unicode_ci,
  `LATITUDE` double DEFAULT NULL,
  `LONGITUDE` double DEFAULT NULL,
  `LOTTERY_NUMS` text COLLATE utf8_unicode_ci,
  `CLASS_MAKEUP` text COLLATE utf8_unicode_ci,
  `BUILDING_TYPE_` int(11) DEFAULT NULL,
  `SUITE` text COLLATE utf8_unicode_ci,
  `NICKNAME` text COLLATE utf8_unicode_ci
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

