CREATE TABLE `housing_data_2022` (
  `dorm` varchar(64) COLLATE utf8_unicode_ci NOT NULL,
  `raw_room_description` varchar(64) COLLATE utf8_unicode_ci NOT NULL,
  `ipv` int(11) NOT NULL,
  `classification` varchar(16) COLLATE utf8_unicode_ci NOT NULL,
  `category` varchar(16) COLLATE utf8_unicode_ci NOT NULL,
