INSERT INTO `related_articles` VALUES ('47 Claremont','https://www.columbiaspectator.com/spectrum/2017/03/24/hack-housing-which-dorms-are-the-loudest-on-campus/','https://www.columbiaspectator.com/spectrum/2017/03/08/hack-housing-how-to-participate-in-the-cubc-housing-exchange/'),('548 West 113th Street (Symposium)','https://www.columbiaspectator.com/spectrum/2017/03/03/hack-housing-which-dorm-should-you-pick-if-you-want-to-feel-like-youre-living-off-campus/','https://www.columbiaspectator.com/spectrum/2017/03/21/hack-housing-which-barnard-dorm-should-you-live-in/'),('600 West 113th Street','https://www.columbiaspectator.com/spectrum/2017/03/21/hack-housing-which-columbia-dorm-should-you-live-in/',''),('600 West 116th Street','https://www.columbiaspectator.com/spectrum/2017/03/08/hack-housing-dorm-and-suite-options-for-barnard-groups-of-1-7/',''),('601 West 110th Street','https://www.columbiaspectator.com/spectrum/2017/03/03/hack-housing-which-dorm-should-you-pick-if-you-want-to-feel-like-youre-living-off-campus/',''),('616 West 116th Street','https://www.columbiaspectator.com/spectrum/2017/03/08/hack-housing-dorm-and-suite-options-for-barnard-groups-of-1-7/',''),('620 West 116th Street','https://www.columbiaspectator.com/spectrum/2017/03/23/hack-housing-barnard-senior-selection-preview/','https://www.columbiaspectator.com/spectrum/2017/03/08/hack-housing-how-to-participate-in-the-cubc-housing-exchange/'),('Andersen Hall','https://www.columbiaspectator.com/spectrum/2017/03/21/hack-housing-which-barnard-dorm-should-you-live-in/',''),('Broadway Hall','https://www.columbiaspectator.com/spectrum/2022/04/15/columbia-dorm-tours-broadway-hall/','https://www.columbiaspectator.com/spectrum/2017/03/10/hack-housing-which-dorms-have-ac/'),('Brooks Hall','https://www.columbiaspectator.com/spectrum/2017/03/21/hack-housing-which-barnard-dorm-should-you-live-in/',NULL),('Carlton Arms','https://www.columbiaspectator.com/spectrum/2017/03/09/hack-housing-dorm-and-suite-options-for-col